# This code has been fully generated by an AI.
"""Ablaufsteuerung: Arena-Scan, Roboter-Registrierung, Kampf. Verbindet Kamera, Modell, Tracking und Spiel."""

import json
import logging
import threading
import time
from dataclasses import dataclass, field

import cv2
import numpy as np

from .arena import Arena, median_plate
from .camera import Camera
from .config import Settings
from .game import Game, RobotInput
from .segmenter import Segmenter
from .tracking import MERGE_PX, Tracker, largest_contour

log = logging.getLogger(__name__)

PLATE_FRAMES = 30
# Mehr als so viel Vordergrund in der Arena heißt: da liegt noch etwas.
EMPTY_FRACTION = 0.004
CIRCLE_POINTS = 20
# Deckt die Modellmaske weniger ab, hat das Modell nur ein Bauteil erwischt.
BLOB_COVER = 0.7


class UserError(Exception):
    """Klartext-Meldung an die Bedienung."""


@dataclass
class Registration:
    slot: int
    snapshot: np.ndarray | None = None
    box: list[float] | None = None
    points: list[tuple[float, float, int]] | None = None
    mask: np.ndarray | None = None
    # Leerbild-Klumpen aus 'Erkennen'; Untergrenze, damit das Modell nicht nur ein Bauteil liefert.
    blob: np.ndarray | None = None
    # Masken der schon gesperrten Roboter im Moment des Schnappschusses; sie wandern ja weiter.
    others: dict[int, np.ndarray] = field(default_factory=dict)

def contour_points(mask: np.ndarray | None, eps: float = 1.5) -> list[list[int]]:
    if mask is None:
        return []
    contour = largest_contour(mask)
    if contour is None:
        return []
    return cv2.approxPolyDP(contour, eps, True).reshape(-1, 2).tolist()


class App:
    def __init__(self, cfg: Settings):
        self.cfg = cfg
        self.camera = Camera(cfg.camera, cfg.camera_width, cfg.camera_height)
        self.segmenter = Segmenter(cfg.model_id, cfg.torch_threads)
        self.arena = Arena.load(cfg.data_dir, cfg.arena_units)
        self.phase = "idle" if self.arena and self.arena.plate is not None else "arena"
        self.message = (
            "" if self.phase == "idle" else "Arena leer räumen, vier Ecken anklicken, dann scannen."
        )
        self.busy: str | None = None
        self.reg: Registration | None = None
        self.confirmed: list[dict] = []
        self.tracker: Tracker | None = None
        self.game: Game | None = None
        self.robots: list = []
        self.contact = False
        self.battle = 0
        self.cam_fps = 0.0
        self.packet: tuple[int, bytes] = (0, b"")
        self._lock = threading.RLock()
        self._stop = threading.Event()

    # ---------- Lebenszyklus ----------

    def start(self) -> None:
        self.camera.start()
        if self.cfg.segment_enabled:
            threading.Thread(target=self.segmenter.load, name="model-load", daemon=True).start()
        else:
            self.segmenter.error = "EdgeTAM ist abgeschaltet, grobe Masken aus dem Leerbild."
        threading.Thread(target=self._loop, name="publish", daemon=True).start()
        # Eigener Thread, damit ein langsames Modell (CPU) die Anzeige nicht ausbremst.
        threading.Thread(target=self._track_loop, name="track", daemon=True).start()

    def stop(self) -> None:
        self._stop.set()
        self.camera.stop()

    def _frame(self) -> np.ndarray:
        frame = self.camera.latest()
        if frame is None:
            raise UserError(self.camera.error or "Noch kein Kamerabild. Kurz warten oder Quelle prüfen.")
        return frame.image

    def _background(self, label: str, fn) -> None:
        if self.busy:
            raise UserError(f"Bitte warten: {self.busy}")
        self.busy = label

        def run():
            try:
                fn()
            except UserError as exc:
                self.message = str(exc)
            except Exception as exc:  # noqa: BLE001 – sonst bliebe die Bedienung ohne Rückmeldung hängen.
                log.exception("%s fehlgeschlagen", label)
                self.message = f"{label} fehlgeschlagen: {exc}"
            finally:
                self.busy = None

        threading.Thread(target=run, name=label, daemon=True).start()

    # ---------- Aktionen der Bedienung ----------

    def act(self, action: str, data: dict) -> None:
        handler = getattr(self, f"do_{action}", None)
        if handler is None:
            raise UserError(f"Unbekannte Aktion '{action}'.")
        # Sonst würde z. B. 'Bestätigen' die grobe Maske nehmen und das Modellergebnis verwerfen.
        if self.busy and action not in ("camera", "abort", "spawn"):
            raise UserError(f"Bitte warten: {self.busy}")
        with self._lock:
            handler(**data)

    def do_camera(self, source: str) -> None:
        self.camera.start(str(source))
        self.message = f"Kamera '{source}' gestartet."

    def do_corners(self, points: list[list[float]]) -> None:
        if len(points) != 4:
            raise UserError("Genau vier Ecken anklicken.")
        self._abort_battle()
        self.arena = Arena(np.array(points, np.float32), self.cfg.arena_units)
        self.arena.save(self.cfg.data_dir)
        self.phase = "arena"
        self.message = "Ecken gespeichert. Arena leer lassen und 'Arena scannen' drücken."

    def do_scan(self) -> None:
        if self.arena is None:
            raise UserError("Zuerst die vier Ecken der Arena anklicken.")
        self._abort_battle()

        def scan():
            frames, last = [], -1
            deadline = time.monotonic() + 10
            while len(frames) < PLATE_FRAMES and time.monotonic() < deadline:
                f = self.camera.latest()
                if f is not None and f.seq != last:
                    frames.append(f.image.copy())
                    last = f.seq
                time.sleep(0.03)
            if len(frames) < 5:
                raise UserError("Zu wenige Kamerabilder für den Scan. Kamera prüfen.")
            self.arena.plate = median_plate(frames)
            self.arena.save(self.cfg.data_dir)
            self.phase = "idle"
            self.message = "Arena gescannt. 'Neuer Kampf' starten."

        self._background("Arena-Scan", scan)

    def do_new_battle(self) -> None:
        if self.arena is None or self.arena.plate is None:
            raise UserError("Erst die Arena einrichten und scannen.")
        self._abort_battle()
        fg = self.arena.foreground(self._frame(), self.cfg.foreground_threshold)
        inside = fg & self.arena.polygon_mask(fg.shape)
        warn = inside.sum() > EMPTY_FRACTION * self.arena.polygon_mask(fg.shape).sum()
        self.reg = Registration(slot=1)
        self.phase = "register"
        self.message = ("Achtung: Die Arena ist nicht leer. Räumen oder neu scannen. " if warn else "") + \
            "Roboter 1 hinstellen, dann 'Erkennen'."

    def do_detect(self) -> None:
        reg = self._reg()
        image = self._frame().copy()
        others = self._tracked_masks()
        fg = self.arena.foreground(image, self.cfg.foreground_threshold)
        for mask in others.values():
            fg &= ~cv2.dilate(mask.astype(np.uint8), np.ones((15, 15), np.uint8)).astype(bool)
        # Schrottroboter zerfallen im Vordergrund in Räder, Platte und Bauteile; nahe Stücke gehören zusammen.
        groups = cv2.dilate(fg.astype(np.uint8), np.ones((MERGE_PX, MERGE_PX), np.uint8))
        n, labels = cv2.connectedComponents(groups)
        areas = np.bincount(labels[fg], minlength=n)
        areas[0] = 0
        if n <= 1 or areas.max() < self.cfg.min_robot_area_px:
            raise UserError(
                f"Kein neuer Roboter gefunden. Roboter {reg.slot} hinstellen oder ins Bild klicken."
            )
        blob = fg & (labels == int(np.argmax(areas)))
        x, y, w, h = cv2.boundingRect(blob.astype(np.uint8))
        reg.snapshot = image
        reg.others = others
        reg.box = [float(x), float(y), float(x + w), float(y + h)]
        # Nur die Box: ein Punkt zieht das Modell auf das Bauteil darunter statt auf den ganzen Roboter.
        reg.points = []
        reg.blob = blob
        reg.mask = blob
        self._predict(reg)

    def do_click(self, x: float, y: float, positive: bool = True) -> None:
        reg = self._reg()
        if reg.snapshot is None:
            reg.snapshot = self._frame().copy()
            reg.others = self._tracked_masks()
            reg.points = []
        reg.points.append((float(x), float(y), 1 if positive else 0))
        self._predict(reg)

    def do_retry(self) -> None:
        reg = self._reg()
        self.reg = Registration(slot=reg.slot)
        self.do_detect()

    def do_confirm(self, name: str = "") -> None:
        reg = self._reg()
        if reg.mask is None or reg.mask.sum() < self.cfg.min_robot_area_px:
            raise UserError("Noch keine brauchbare Maske. 'Erkennen' oder ins Bild klicken.")
        if not self.segmenter.ready.is_set():
            raise UserError(self.segmenter.error or "Modell lädt noch, gleich noch einmal 'Bestätigen'.")
        name = name.strip() or f"Roboter {reg.slot}"
        if self.tracker is None:
            self.segmenter.reset_tracking()
            self.tracker = Tracker(self.arena, self.segmenter)
        tracker = self.tracker

        def lock_in():
            # Das Ankerbild ist der Schnappschuss, zu dem die Maske gehört, nicht das aktuelle Bild.
            tracker.add(reg.slot, name, reg.snapshot, reg.mask, time.monotonic())
            with self._lock:
                if self.tracker is not tracker or self.reg is not reg:
                    return
                self.confirmed.append({"slot": reg.slot, "name": name, "mask": reg.mask})
                if reg.slot == 1:
                    self.reg = Registration(slot=2)
                    self.message = ("Roboter 1 gesperrt und wird verfolgt. "
                                    "Roboter 2 hinstellen, dann 'Erkennen'.")
                else:
                    self.reg = None
                    self.phase = "ready"
                    self.message = "Beide Roboter erkannt und verfolgt. 'Start' drücken."

        self._background("Roboter sperren", lock_in)

    def _tracked_masks(self) -> dict[int, np.ndarray]:
        if self.tracker is None:
            return {}
        return self.tracker.image_masks()

    def do_start(self) -> None:
        if self.phase != "ready" or len(self.confirmed) != 2 or self.tracker is None:
            raise UserError("Erst beide Roboter registrieren.")
        self.battle += 1
        self.game = Game(self.cfg, [(c["slot"], c["name"]) for c in self.confirmed], time.monotonic())
        self.phase = "fight"
        self.message = "Kampf läuft."

    def do_spawn(self, kind: str) -> None:
        if self.phase != "fight" or self.game is None:
            raise UserError("Spawnen geht nur im laufenden Kampf.")
        if kind not in ("obstacle", "powerup"):
            raise UserError("Unbekanntes Objekt.")
        if not self.game.spawn(kind, time.monotonic(), self._robot_inputs()):
            raise UserError("Kein freier Platz zum Spawnen.")

    def do_abort(self) -> None:
        self._abort_battle()
        self.phase = "idle" if self.arena and self.arena.plate is not None else "arena"
        self.message = "Kampf abgebrochen."

    def _abort_battle(self) -> None:
        if self.tracker is not None:
            self.segmenter.reset_tracking()
        self.tracker = None
        self.game = None
        self.reg = None
        self.confirmed = []
        self.robots = []
        self.contact = False

    def _reg(self) -> Registration:
        if self.phase != "register" or self.reg is None:
            raise UserError("Gerade wird kein Roboter registriert. 'Neuer Kampf' drücken.")
        return self.reg

    def _predict(self, reg: Registration) -> None:
        if not self.segmenter.ready.is_set():
            # Ohne Modell bleibt der Leerbild-Klumpen die Maske; Klicks können dann nichts verfeinern.
            self.message = self.segmenter.error or "Modell lädt noch, vorerst grobe Maske aus dem Leerbild."
            return
        snapshot, box, points = reg.snapshot, reg.box, list(reg.points or [])

        def run():
            mask = self.segmenter.predict(snapshot, box, points)
            blob = reg.blob
            # Sobald geklickt wurde, entscheidet der Mensch; vorher darf das Modell keine Teile weglassen.
            if not points and blob is not None and (mask & blob).sum() < BLOB_COVER * blob.sum():
                mask |= blob
            for other in reg.others.values():
                mask &= ~other
            if self.reg is reg:
                reg.mask = mask
                self.message = (f"Maske für Roboter {reg.slot} prüfen. Linksklick fügt hinzu, Rechtsklick "
                                "entfernt. Passt es: Namen eingeben und 'Bestätigen'.")

        self._background("Segmentierung", run)

    # ---------- Verarbeitung ----------

    def _robot_inputs(self) -> list[RobotInput]:
        return [RobotInput(o.id, o.present, o.pos, o.vel, o.radius, o.inside, o.outline) for o in self.robots]

    def _loop(self) -> None:
        last_seq, fps_t, fps_n = -1, time.monotonic(), 0
        while not self._stop.is_set():
            frame = self.camera.latest()
            if frame is None or frame.seq == last_seq:
                time.sleep(0.004)
                continue
            last_seq = frame.seq
            fps_n += 1
            if frame.t - fps_t >= 1.0:
                self.cam_fps, fps_t, fps_n = fps_n / (frame.t - fps_t), frame.t, 0
            try:
                with self._lock:
                    self._publish(frame.image, frame.seq)
            except Exception:  # noqa: BLE001 – ein kaputter Frame darf die Anzeige nicht beenden.
                log.exception("Anzeige fehlgeschlagen")

    def _track_loop(self) -> None:
        last_seq = -1
        while not self._stop.is_set():
            frame = self.camera.latest()
            if frame is None or frame.seq == last_seq or self.tracker is None:
                time.sleep(0.004)
                continue
            # Immer das neueste Bild: lieber Bilder auslassen als dem Geschehen hinterherlaufen.
            last_seq = frame.seq
            try:
                self._process(frame.image, frame.t)
            except Exception:  # noqa: BLE001 – ein kaputter Frame darf das Tracking nicht beenden.
                log.exception("Tracking fehlgeschlagen")

    def _process(self, image: np.ndarray, t: float) -> None:
        tracker = self.tracker
        if tracker is None or self.phase not in ("register", "ready", "fight", "finished"):
            return
        robots, contact = tracker.update(image, t)
        with self._lock:
            # Während des Modelllaufs kann abgebrochen oder neu begonnen worden sein.
            if self.tracker is tracker:
                self._apply(robots, contact, t)

    def _apply(self, robots: list, contact: bool, t: float) -> None:
        self.robots, self.contact = robots, contact
        if self.phase == "fight" and self.game is not None:
            self.game.tick(t, self._robot_inputs(), self.contact)
            if self.game.finished:
                self.phase = "finished"
                winner = self.game.player(self.game.winner).name if self.game.winner else None
                self.message = f"{winner} gewinnt!" if winner else "Unentschieden!"

    # ---------- Ausgabe an die Oberfläche ----------

    def _to_image(self, pos) -> list[float] | None:
        if pos is None or self.arena is None:
            return None
        return self.arena.to_image(np.asarray(pos, np.float32))[0].round(1).tolist()

    def _circle(self, center, radius: float) -> list[list[float]]:
        angles = np.linspace(0, 2 * np.pi, CIRCLE_POINTS, endpoint=False)
        pts = np.stack([center[0] + radius * np.cos(angles), center[1] + radius * np.sin(angles)], axis=1)
        return self.arena.to_image(pts).round(1).tolist()

    def state(self, t: float) -> dict:
        names = {c["slot"]: c["name"] for c in self.confirmed}
        robots = []
        for o in self.robots:
            p = self.game.player(o.id) if self.game else None
            robots.append({
                "id": o.id, "name": names.get(o.id, ""), "present": o.present,
                "hp": round(p.hp, 1) if p else self.cfg.start_hp, "max_hp": self.cfg.start_hp,
                "outside": bool(p and p.outside_since is not None),
                "center": self._to_image(o.pos),
                "contour": [] if o.outline is None else self.arena.to_image(o.outline).round(1).tolist(),
            })
        items = []
        events = []
        if self.game:
            for i in self.game.items:
                items.append({"id": i.id, "kind": i.kind, "center": self._to_image(i.pos),
                              "poly": self._circle(i.pos, i.radius), "armed": i.armed(t),
                              "ttl": round(i.expires - t, 1)})
            for e in self.game.events:
                events.append({**e, "pos": self._to_image(e.get("pos")), "t": None})
        reg = self.reg
        live = {o.id for o in self.robots}
        return {
            "phase": self.phase, "battle": self.battle, "message": self.message, "busy": self.busy,
            "camera": {"source": self.camera.source, "error": self.camera.error,
                       "fps": round(self.cam_fps, 1)},
            "model": {"ready": self.segmenter.ready.is_set(), "error": self.segmenter.error,
                      "device": self.segmenter.device_label},
            "arena": {"corners": self.arena.corners.tolist() if self.arena else [],
                      "scanned": bool(self.arena and self.arena.plate is not None)},
            "register": None if reg is None else {
                "slot": reg.slot, "points": [list(p) for p in reg.points or []],
                "contour": contour_points(reg.mask)},
            "confirmed": [{"slot": c["slot"], "name": c["name"],
                           "contour": [] if c["slot"] in live else contour_points(c["mask"])}
                          for c in self.confirmed] if self.phase in ("register", "ready") else [],
            "robots": robots, "contact": self.contact, "items": items, "events": events,
            "winner": (self.game.player(self.game.winner).name
                       if self.game and self.game.finished and self.game.winner else None),
            "finished": bool(self.game and self.game.finished),
        }

    def _publish(self, image: np.ndarray, seq: int) -> None:
        h, w = image.shape[:2]
        scale = min(1.0, self.cfg.stream_max_width / w)
        small = cv2.resize(image, (int(w * scale), int(h * scale))) if scale < 1 else image
        ok, jpeg = cv2.imencode(".jpg", small, [cv2.IMWRITE_JPEG_QUALITY, self.cfg.jpeg_quality])
        if not ok:
            return
        state = self.state(time.monotonic())
        state["frame"] = {"w": w, "h": h}
        header = json.dumps(state, separators=(",", ":")).encode()
        self.packet = (seq, len(header).to_bytes(4, "little") + header + jpeg.tobytes())

    def publish_idle(self) -> None:
        """Ohne Kamerabild trotzdem den Zustand senden, damit Fehlermeldungen ankommen."""
        if self.camera.latest() is not None:
            return
        state = self.state(time.monotonic())
        state["frame"] = None
        header = json.dumps(state, separators=(",", ":")).encode()
        self.packet = (self.packet[0] + 1, len(header).to_bytes(4, "little") + header)
